<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$notes=trim($_POST['notes']??'');if($name){$st=$pdo->prepare("INSERT INTO customers(name,phone,email,notes) VALUES(?,?,?,?)");$st->execute([$name,$phone,$email?:null,$notes]);flash('Customer added successfully.');}else flash('Customer name is required.','error');redirect('customers.php');}
$q=trim($_GET['q']??'');$st=$pdo->prepare("SELECT c.*,COALESCE((SELECT SUM(balance) FROM sales s WHERE s.customer_id=c.id),0) due FROM customers c WHERE c.name LIKE ? OR c.phone LIKE ? ORDER BY c.id DESC");$st->execute(["%$q%","%$q%"]);$rows=$st->fetchAll();layout_start('Customers','customers');?>
<div class="page-actions"><div><p class="muted">Keep customer details and payment dues organized.</p></div><button class="btn primary" onclick="document.getElementById('customerForm').classList.toggle('hidden')">＋ Add customer</button></div><section class="panel form-panel hidden" id="customerForm"><h3>New customer</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Full name *<input name="name" required></label><label>Phone<input name="phone" inputmode="tel"></label><label>Email<input name="email" type="email"></label><label>Notes<input name="notes"></label><div class="form-actions"><button class="btn primary">Save customer</button></div></form></section><section class="panel table-panel"><div class="panel-head"><div><h3>Customer directory</h3><p class="muted"><?=count($rows)?> records</p></div><form class="search-form"><input name="q" value="<?=h($q)?>" placeholder="Search name or phone…"><button class="btn secondary">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th>Email</th><th class="right">Outstanding</th><th>Joined</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="person-cell"><span class="avatar"><?=h(strtoupper(substr($r['name'],0,1)))?></span><b><?=h($r['name'])?></b></div></td><td><?=h($r['phone']?:'—')?></td><td><?=h($r['email']?:'—')?></td><td class="right <?=((float)$r['due']>0?'danger-text':'')?>"><?=money($r['due'])?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="empty">No customers found.</td></tr><?php endif;?></tbody></table></div></section><?php layout_end();?>
